use parth_db::exec::execute; use parth_db::Database; fn count(db: &Database, sql: &str) -> usize { execute(db, sql).unwrap().rows.len() } #[test] fn null_and_precedence() { let dir = std::env::temp_dir().join(format!("parth_in_sem_{}", std::process::id())); let _ = std::fs::remove_dir_all(&dir); let db = Database::open(&dir).unwrap(); execute(&db, "CREATE TABLE t (id INT PRIMARY KEY, v INT)").unwrap(); execute(&db, "INSERT INTO t VALUES (1, 1), (2, 2), (3, NULL)").unwrap(); assert_eq!(count(&db, "SELECT * FROM t WHERE id NOT IN (1, NULL)"), 0); assert_eq!(count(&db, "SELECT * FROM t WHERE id IN (1, NULL)"), 1); assert_eq!(count(&db, "SELECT * FROM t WHERE id NOT IN (7, 8)"), 3); assert_eq!(count(&db, "SELECT * FROM t WHERE id IN (1, 2) OR id = 3 AND v IS NULL"), 3); assert_eq!(count(&db, "SELECT * FROM t WHERE id = 3 AND v IS NULL OR id IN (1)"), 2); assert_eq!(count(&db, "SELECT * FROM t WHERE id = 1 OR id BETWEEN 2 AND 3 AND v = 2"), 2); let ok = vec!["1"; 256].join(", "); assert_eq!(count(&db, &format!("SELECT * FROM t WHERE id IN ({})", ok)), 1); let big = vec!["1"; 257].join(", "); assert!(execute(&db, &format!("SELECT * FROM t WHERE id IN ({})", big)).is_err()); execute(&db, "UPDATE t SET v = 99 WHERE id IN (1, 2)").unwrap(); assert_eq!(count(&db, "SELECT * FROM t WHERE v = 99"), 2); execute(&db, "DELETE FROM t WHERE id BETWEEN 2 AND 3").unwrap(); assert_eq!(count(&db, "SELECT * FROM t"), 1); let _ = std::fs::remove_dir_all(&dir); }